import sys
from itertools import product

m, n = map(int, sys.stdin.read().split())
cnt = 0
for cells in product(range(3), repeat=m * n):
    ok = True
    for r in range(m):
        for c in range(n):
            v = cells[r * n + c]
            if c + 1 < n and cells[r * n + c + 1] == v:
                ok = False
            if r + 1 < m and cells[(r + 1) * n + c] == v:
                ok = False
    if ok:
        cnt += 1
print(cnt % (10**9 + 7))

